{
  "items": [
    {
      "name": "Polynomial.degree_sub_le_of_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R} {a b : WithBot ℕ},\n  p.degree ≤ a → q.degree ≤ b → (p - q).degree ≤ max a b"
    },
    {
      "name": "Polynomial.coeff_sub",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (p q : Polynomial R) (n : ℕ), (p - q).coeff n = p.coeff n - q.coeff n"
    },
    {
      "name": "Polynomial.degree_sub_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (p q : Polynomial R), (p - q).degree ≤ max p.degree q.degree"
    },
    {
      "name": "Polynomial.natDegree_sub_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (p q : Polynomial R), (p - q).natDegree ≤ max p.natDegree q.natDegree"
    },
    {
      "name": "Polynomial.natDegree_sub_le_of_le",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} {n m : ℕ} [inst : Ring R] {p q : Polynomial R},\n  p.natDegree ≤ m → q.natDegree ≤ n → (p - q).natDegree ≤ max m n"
    },
    {
      "name": "MvPolynomial.totalDegree_sub",
      "module_name": "Mathlib.Algebra.MvPolynomial.CommRing",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommRing R] (a b : MvPolynomial σ R),\n  (a - b).totalDegree ≤ max a.totalDegree b.totalDegree"
    }
  ]
}
